\label{def:compatible-couplings}
  The set of joint distributions compatible with the two prescribed target--source marginals is
  \begin{equation}
    \Delta(P)=
    \{Q_{MXY}:Q_{MX}\!=P_{MX},\ Q_{MY}\!=P_{MY}\}.
    \label{eq:compatible-couplings}
  \end{equation}
  Each $Q\in\Delta(P)$ is called a compatible coupling: it specifies the dependence between $X$ and $Y$ while preserving both target--source marginals.

\label{def:broja-info}
  The BROJA unique information carried by $X$ relative to $Y$ \citep{bertschinger2014quantifying} is
  \begin{equation}
    \operatorname{UI}^{\mathrm{BROJA}}_X
    :=
    \inf_{Q\in\Delta(P)} I_Q(M;X\mid Y).
    \label{eq:broja-unique}
  \end{equation}
  The associated marginal-constrained union information \citep{griffith2014quantifying} is
  \begin{equation}
    I_{\cup}^{\mathrm{BROJA}}(M;X,Y)
    :=
    \inf_{Q\in\Delta(P)} I_Q(M;X,Y).
    \label{eq:broja-union}
  \end{equation}

\label{ass:gaussian-marginals}
  The prescribed marginals $P_{MX}$ and $P_{MY}$ are nondegenerate jointly Gaussian distributions with a common target marginal
  \begin{equation}
    M\sim\mathcal{N}(\mu_M,\Sigma_M),
    \qquad
    \Sigma_M\succ0.
    \label{eq:gaussian-target}
  \end{equation}
  Here, nondegeneracy means that the joint covariance matrices $\Sigma_{(M,X)}$ and $\Sigma_{(M,Y)}$ are positive definite. No Gaussian assumption is imposed on an arbitrary compatible coupling $Q_{MXY}\in\Delta(P)$.

\label{prop:max-det}
  Let $\lambda_1,\ldots,\lambda_{d_M}$ and $T$ be defined by Equations~\eqref{eq:generalized-eigenvalues}--\eqref{eq:simultaneous-diagonalization}. Define
  \begin{equation}
    D:=\operatorname{diag}(d_1,\ldots,d_{d_M}),
    \qquad
    d_i:=\min\{1,\lambda_i\}.
    \label{eq:D-def}
  \end{equation}

  Recall that \begin{equation}
    T:=U^\top\Gamma_X^{-1/2}.
  \end{equation}
  Then the optimizer in Equation~\eqref{eq:max-det-posterior-covariance} exists uniquely and is given by
  \begin{equation}
    \Gamma^\star=T^{-1}DT^{-\top}.
    \label{eq:gamma-star}
  \end{equation}
  In particular,
  \begin{equation}
    \det\Gamma^\star
    =
    \det(T^{-1})^2
    \prod_{i=1}^{d_M}\min\{1,\lambda_i\}.
    \label{eq:gamma-star-det}
  \end{equation}

We first verify feasibility. Since every $\lambda_i$ is positive, $D\succ0$. Moreover,
  \begin{equation}
    D\preceq I_{d_M},
    \qquad
    D\preceq\Lambda.
  \end{equation}
  Using Equations~\eqref{eq:simultaneous-diagonalization}, \eqref{eq:congruence-order} and~\eqref{eq:gamma-star},
  \begin{equation}
    \Gamma_X-\Gamma^\star
    =
    T^{-1}(I_{d_M}-D)T^{-\top}
    \succeq0
  \end{equation}
  and
  \begin{equation}
    \Gamma_Y-\Gamma^\star
    =
    T^{-1}(\Lambda-D)T^{-\top}
    \succeq0.
  \end{equation}
  Hence $\Gamma^\star\in\mathcal{F}_{X,Y}$.

  Now let $\Gamma\in\mathcal{F}_{X,Y}$ be arbitrary and define
  \begin{equation}
    C:=T\Gamma T^\top.
    \label{eq:C-def}
  \end{equation}
  By the congruence lemma~\eqref{eq:congruence-order},
  \begin{equation}
    C\succ0,
    \qquad
    C\preceq I_{d_M},
    \qquad
    C\preceq\Lambda.
  \end{equation}
  Therefore, for every $i$,
  \begin{equation}
    C_{ii}\leq1,
    \qquad
    C_{ii}\leq\lambda_i,
  \end{equation}
  and consequently
  \begin{equation}
    C_{ii}\leq d_i=\min\{1,\lambda_i\}.
  \end{equation}
  Hadamard's determinant inequality~\eqref{eq:hadamard} gives
  \begin{equation}
    \det C
    \leq
    \prod_{i=1}^{d_M}C_{ii}
    \leq
    \prod_{i=1}^{d_M}d_i
    =
    \det D.
    \label{eq:C_D_inequality}
  \end{equation}
  Taking determinants in Equation~\eqref{eq:C-def}, and applying the multiplicativity of the determinant, gives
  \begin{align}
    \det\Gamma
     & =
    \det(T^{-1})^2\det C
    \\
     & \leq
    \det(T^{-1})^2\det D
    =
    \det\Gamma^\star.
  \end{align}
  Thus, $\Gamma^\star$ is optimal.

  Finally, to prove uniqueness, assume that $\det C = \det D$. Then both inequalities in Equation~\eqref{eq:C_D_inequality} must be equalities. Equality in Hadamard's inequality~\eqref{eq:hadamard} requires the positive-definite matrix $C$ to be diagonal. Since $0<C_{ii}\leq d_i$ for every $i$, equality $\prod_i C_{ii}=\prod_i d_i$ forces $C_{ii}=d_i$ for every $i$: if $C_{jj}<d_j$ for some $j$, then
  \begin{equation}
    \det C = \prod_{i=1}^{d_M}C_{ii}
    \leq
    C_{jj}\prod_{i\neq j}d_i
    <
    \prod_{i=1}^{d_M}d_i = \det D,
  \end{equation}
  a contradiction. Hence $C=D$, and therefore $\Gamma=\Gamma^\star$ and the optimizer is unique.

\label{prop:broja-lower-bound}
  Under \cref{ass:gaussian-marginals},
  \begin{equation}
    I_{\cup}^{\mathrm{BROJA}}(M;X,Y)
    \geq
    \frac12\log_2
    \frac{\det\Sigma_M}{\det\Gamma^\star}.
    \label{eq:broja-lower-bound}
  \end{equation}
  The proof is given in~\cref{supp:proof-broja-lower-bound}.

\label{thm:gaussian-broja}
  Under \cref{ass:gaussian-marginals}, let $\lambda_1,\ldots,\lambda_{d_M}$ be the generalized eigenvalues defined by
  \begin{equation}
    \Gamma_Yv_i=\lambda_i\Gamma_Xv_i,
  \end{equation}
  and let $\Gamma^\star$ be defined by Equation~\eqref{eq:gamma-star}. Then
  \begin{equation}
    I_{\cup}^{\mathrm{BROJA}}(M;X,Y)
    =
    \frac12\log_2
    \frac{\det\Sigma_M}{\det\Gamma^\star}.
    \label{eq:main-union}
  \end{equation}
  Consequently,
  \begin{equation}
    \operatorname{UI}^{\mathrm{BROJA}}_X
    =
    \frac12
    \sum_{i=1}^{d_M}[\log_2\lambda_i]_+,
    \label{eq:main-ui-x}
  \end{equation}
  and
  \begin{equation}
    \operatorname{UI}^{\mathrm{BROJA}}_Y
    =
    \frac12
    \sum_{i=1}^{d_M}[-\log_2\lambda_i]_+.
    \label{eq:main-ui-y}
  \end{equation}
  Moreover, the infimum in the BROJA optimization is attained by a compatible jointly Gaussian coupling.

We first construct a Gaussian experiment $Z^\star$ attaining the lower bound of \cref{prop:broja-lower-bound}. By \cref{prop:max-det},
  \begin{equation}
    0\prec\Gamma^\star\preceq\Gamma_X\preceq\Sigma_M.
  \end{equation}
  Since inversion reverses the Loewner order, the matrix
  \begin{equation}
    J^\star
    :=
      (\Gamma^\star)^{-1}-\Sigma_M^{-1}
    \label{eq:J-star}
  \end{equation}
  is positive semidefinite. Define the linear Gaussian experiment
  \begin{equation}
    \begin{aligned}
      Z^\star
       & :=
           (J^\star)^{1/2}(M-\mu_M)+\varepsilon, \\
      \varepsilon
       & \sim\mathcal{N}(0,I_{d_M}),
      \qquad
      \varepsilon\perp\!\!\!\perp M.
    \end{aligned}
    \label{eq:Z-star}
  \end{equation}
  Applying the posterior-precision identity \eqref{eq:posterior-precision} gives
  \begin{equation}
    \operatorname{Cov}(M\mid Z^\star)^{-1}
    =
    \Sigma_M^{-1}+J^\star
      =
      (\Gamma^\star)^{-1}.
  \end{equation}
  Therefore,
  \begin{equation}
    \operatorname{Cov}(M\mid Z^\star)
    =
    \Gamma^\star.
    \label{eq:Z-star-posterior}
  \end{equation}
  \cref{prop:max-det} also gives
  \begin{equation}
    \Gamma^\star\preceq\Gamma_X,
    \qquad
    \Gamma^\star\preceq\Gamma_Y.
  \end{equation}

  Since $(M,Z^\star)$ is jointly Gaussian,
\begin{align}
I(M;Z^\star)
& =
\frac12\log_2
\frac{\det\Sigma_M}
{\det\operatorname{Cov}(M| Z^\star)},

\\
& =
\frac12\log_2
\frac{\det\Sigma_M}{\det\Gamma^\star}.
\end{align}



  \vspace{0.6em}
  We next show that the optimum is attained by a compatible jointly
  Gaussian coupling $Q \in \Delta(P)$.
  Since $\operatorname{Cov}(M\mid Z^\star)=\Gamma^\star$
  by Equation~\eqref{eq:Z-star-posterior}, with
  $\Gamma^\star\preceq\Gamma_X$ and $\Gamma^\star\preceq\Gamma_Y$,
  \cref{lem:gaussian-garbling} (\cref{app:gaussian-garbling}), applied
  with $Z=Z^\star$ and $A=X$ and then with $A=Y$, provides
  linear-Gaussian garbling
  kernels $K_X(dx\mid z)$ and $K_Y(dy\mid z)$
  that generate copies $X^\star$ and $Y^\star$ of the source
  experiments from $Z^\star$. Generate $X^\star$ and $Y^\star$
  independently conditional on $Z^\star$. Then
  \begin{equation}
    (M,X^\star)\overset{d}{=}(M,X),
    \qquad
    (M,Y^\star)\overset{d}{=}(M,Y),
  \end{equation}
  so the joint law of $(M,X^\star,Y^\star)$ belongs to $\Delta(P)$. Moreover,
  \begin{equation}
    M-Z^\star-(X^\star,Y^\star),
  \end{equation}
  and therefore, from the data-processing inequality~\eqref{eq:data-processing},
  \begin{equation}
    I(M;X^\star,Y^\star)\leq I(M;Z^\star).
    \label{eq:XY_Z-star-data-processing}
  \end{equation}
  Combining now Equation \eqref{eq:broja-lower-bound} from \cref{prop:broja-lower-bound}, the definition of BROJA union information \eqref{eq:broja-union} and (\ref{eq:XY_Z-star-data-processing}) gives
  \begin{equation}
    \begin{aligned}
      \frac12\log_2
      \frac{\det\Sigma_M}{\det\Gamma^\star}
       & \leq
      I_{\cup}^{\mathrm{BROJA}}(M;X,Y)
      \\
       & \leq
      I(M;X^\star,Y^\star)
      \\
       & \leq
      I(M;Z^\star)
      =
      \frac12\log_2
      \frac{\det\Sigma_M}{\det\Gamma^\star}.
    \end{aligned}
  \end{equation}
  Every inequality is therefore an equality, proving that $(M,X^\star,Y^\star)$ is an attaining jointly Gaussian coupling, and proving Equation~\eqref{eq:main-union}.

  It remains to evaluate the two unique-information components. By Equation~\eqref{eq:ui-union-relation} and Equation~\eqref{eq:main-union},
  \begin{align}
    \operatorname{UI}^{\mathrm{BROJA}}_X
     & =
    \frac12\log_2
    \frac{\det\Sigma_M}{\det\Gamma^\star}
    -\frac12\log_2
    \frac{\det\Sigma_M}{\det\Gamma_Y}
    \\
     & =\frac12\log_2
    \frac{\det\Gamma_Y}{\det\Gamma^\star}.
    \label{eq:ui-x-det-ratio}
  \end{align}
  Using Equations~\eqref{eq:simultaneous-diagonalization} and~\eqref{eq:gamma-star},
  \begin{equation}
    \Gamma_Y=T^{-1}\Lambda T^{-\top},
    \qquad
    \Gamma^\star=T^{-1}DT^{-\top}.
  \end{equation}
  Consequently,
 \begin{equation}
\frac{\det\Gamma_Y}{\det\Gamma^\star}
=
\frac{\det\Lambda}{\det D}
=
\prod_{i=1}^{d_M}
\frac{\lambda_i}{\min\{1,\lambda_i\}}.
\end{equation}
For each $i$,
\begin{equation}
\log_2
\frac{\lambda_i}{\min\{1,\lambda_i\}}
=
[\log_2\lambda_i]_+.
\end{equation}
Substitution into Equation~\eqref{eq:ui-x-det-ratio} proves
Equation~\eqref{eq:main-ui-x}.

Finally, interchanging $X$ and $Y$ replaces the multiset of
generalized eigenvalues by
$\{\lambda_i^{-1}\}_{i=1}^{d_M}$. Hence
\begin{equation}
\operatorname{UI}^{\mathrm{BROJA}}_Y
=
\frac12
\sum_{i=1}^{d_M}[\log_2\lambda_i^{-1}]_+
=
\frac12
\sum_{i=1}^{d_M}[-\log_2\lambda_i]_+,
\end{equation}
which proves Equation~\eqref{eq:main-ui-y}.

\label{lem:posterior-mse}
  Let $M$ have finite second moments. If $M-Z-A$ is a Markov chain, then
  \begin{equation}
    \bar{\Gamma}_Z\preceq\bar{\Gamma}_A.
    \label{eq:posterior-error-order}
  \end{equation}

Since $M$ is Gaussian, Equation~\eqref{eq:gaussian-entropy} gives
  \begin{align}
    I(M;Z) & = h(M)-h(M\mid Z)
    \nonumber
    \\
           & =\frac12\log_2\big((2\pi e)^{d_M}\det \Sigma_M \big) -h(M\mid Z).
    \label{eq:info-lower-bound-expansion}
  \end{align}
  If $h(M\mid Z)=-\infty$, then $I(M;Z)=+\infty$ and there is nothing to prove, so assume $h(M\mid Z)>-\infty$. For the second term in \eqref{eq:info-lower-bound-expansion}, we have
  \begin{align}
    h(M\mid Z)
     & =
    h\big(M-\mathbb{E}[M\mid Z]\,\big|\,Z\big),
    \label{eq:shift-M}
    \\
     & \leq
    h\big(M-\mathbb{E}[M\mid Z]\big),
    \label{eq:drop-conditioning}
    \\
     & \leq
    h\big( \mathcal{N}(0,\bar{\Gamma}_Z) \big),
    \label{eq:Gaussian-maximum-entropy}
    \\
     & =
    \frac12\log_2\big((2\pi e)^{d_M}\det\bar{\Gamma}_Z\big).
    \label{eq:conditional-entropy-bound}
  \end{align}
  In \eqref{eq:shift-M} we used that the conditional mean $\mathbb{E}[M\mid Z]$ is a function of $Z$, so the conditional differential entropy is invariant under this shift. In \eqref{eq:drop-conditioning} we drop the conditioning on $Z$, which can only increase the differential entropy. In \eqref{eq:Gaussian-maximum-entropy} we apply the Gaussian maximum-entropy bound, which states that among all random vectors with a given covariance matrix, the Gaussian distribution has the largest differential entropy. Here, the covariance of $M-\mathbb{E}[M\mid Z]$ is exactly $\bar{\Gamma}_Z$ by \eqref{eq:average-posterior-error}. Substituting \eqref{eq:conditional-entropy-bound} into \eqref{eq:info-lower-bound-expansion} cancels the factors $(2\pi e)^{d_M}$ and yields \eqref{eq:posterior-error-information-bound}.

\label{lem:gaussian-garbling}
  Let $M \sim \mathcal{N}(\mu_M, \Sigma_M)$ with $\Sigma_M \succ 0$, and let
  \begin{align}
    A & = \mu_A + H_A (M - \mu_M) + N_A, & N_A & \sim \mathcal{N}(0, R_A),
    \label{eq:gaussian-experiment-A}
    \\
    Z & = \mu_Z + H_Z (M - \mu_M) + N_Z, & N_Z & \sim \mathcal{N}(0, R_Z),
  \end{align}
  with $R_A \succ 0$, $R_Z \succ 0$, and $N_A, N_Z$ independent of $M$. Let $\Gamma_A := \operatorname{Cov}(M \mid A)$ and $\Gamma_Z := \operatorname{Cov}(M \mid Z)$, write $J_A := H_A^\top R_A^{-1} H_A$ and $J_Z := H_Z^\top R_Z^{-1} H_Z$, and assume
  \begin{equation}
    \Gamma_Z \preceq \Gamma_A .
    \label{eq:garbling-hypotheses}
  \end{equation}
  Then there exist a matrix $G$ and a matrix $S \succeq 0$ such that, for $W \sim \mathcal{N}(0, S)$ independent of $(M, Z)$, the variable
  \begin{equation}
    A' := \mu_A + G (Z - \mu_Z) + W
    \label{eq:garbled-copy}
  \end{equation}
  satisfies $(M, A') \overset{d}{=} (M, A)$ and the Markov chain $M - Z - A'$. In particular, $(M, Z, A')$ is jointly Gaussian. If $J_Z \succ 0$, one can take
  \begin{equation}
    G := H_A J_Z^{-1} H_Z^\top R_Z^{-1},
    \qquad
    S := R_A - H_A J_Z^{-1} H_A^\top .
    \label{eq:garbling-G-S}
  \end{equation}

\textbf{Case 1: $J_Z \succ 0$.} We show that $G$ and $S$ defined in~\eqref{eq:garbling-G-S} have the stated properties.

  \textbf{Step 1: $J_A \preceq J_Z$.} By the posterior-precision identity~\eqref{eq:posterior-precision}, $\Gamma_A^{-1} = \Sigma_M^{-1} + J_A$ and $\Gamma_Z^{-1} = \Sigma_M^{-1} + J_Z$. Since $0 \prec \Gamma_Z \preceq \Gamma_A$ and matrix inversion reverses the Loewner order (\cref{subsec:gaussian-matrix-tools}), $\Gamma_A^{-1} \preceq \Gamma_Z^{-1}$, and therefore
  \begin{equation}
    J_A = \Gamma_A^{-1} - \Sigma_M^{-1}
    \preceq
    \Gamma_Z^{-1} - \Sigma_M^{-1} = J_Z .
    \label{eq:JA-JZ}
  \end{equation}

  \textbf{Step 2: $G$ reproduces the channel matrix.} By the definition of $J_Z$,
  \begin{equation}
    G H_Z = H_A J_Z^{-1} \bigl(H_Z^\top R_Z^{-1} H_Z\bigr) = H_A J_Z^{-1} J_Z = H_A .
    \label{eq:G-reproduces}
  \end{equation}

  \textbf{Step 3: $S \succeq 0$.} Consider the block matrix
  \begin{equation}
    \begin{pmatrix} R_A & H_A \\ H_A^\top & J_A \end{pmatrix}.
    \label{eq:block-A}
  \end{equation}
  Since $R_A \succ 0$ and its Schur complement with respect to $R_A$ is $J_A - H_A^\top R_A^{-1} H_A = 0 \succeq 0$, the matrix~\eqref{eq:block-A} is positive semidefinite by the Schur complement criterion~\eqref{eq:schur-criterion}. Adding the positive-semidefinite matrix $\operatorname{diag}(0, J_Z - J_A)$, see \eqref{eq:JA-JZ}, gives
  \begin{equation}
    \begin{pmatrix} R_A & H_A \\ H_A^\top & J_Z \end{pmatrix} \succeq 0 .
    \label{eq:block-Z}
  \end{equation}
  Since $J_Z \succ 0$, the criterion~\eqref{eq:schur-criterion-R} applied to~\eqref{eq:block-Z} shows that the Schur complement $R_A - H_A J_Z^{-1} H_A^\top = S$ is positive semidefinite.

  \textbf{Step 4: the law of $(M, A')$.} Substituting $Z - \mu_Z = H_Z (M - \mu_M) + N_Z$ into \eqref{eq:garbled-copy} and using \eqref{eq:G-reproduces},
  \begin{equation}
    A' = \mu_A + H_A (M - \mu_M) + N', \qquad N' := G N_Z + W .
  \end{equation}
  This has the same form as $A$ in \eqref{eq:gaussian-experiment-A}, with the same mean and channel matrix. We only need to check that the noise $N'$, which has zero mean, has the same covariance as $N_A$. Indeed, $N'$ is Gaussian and independent of $M$. Since $N_Z$ and $W$ are independent, and $J_Z$ is symmetric, its covariance is
  \begin{equation}
    \begin{aligned}
      \operatorname{Cov}(N')
       & = G\operatorname{Cov}(N_Z)G^\top + \operatorname{Cov}(W)
      \\
       & = G R_Z G^\top + S
      \\
       & = H_A J_Z^{-1} H_Z^\top R_Z^{-1}\, R_Z\, R_Z^{-1} H_Z J_Z^{-1} H_A^\top + S
      \\
       & = H_A J_Z^{-1} \bigl(H_Z^\top R_Z^{-1} H_Z\bigr) J_Z^{-1} H_A^\top + S
      \\
       & = H_A J_Z^{-1} H_A^\top + S = R_A .
    \end{aligned}
  \end{equation}
  Thus $(M, A')$ is jointly Gaussian with the same mean, channel matrix, and noise covariance as $(M, A)$, so $(M, A') \overset{d}{=} (M, A)$. The Markov chain $M - Z - A'$ holds because $A'$ is a function of $Z$ and of $W$, which is independent of $(M, Z)$.

  \textbf{Case 2: $J_Z$ singular.} Let $U := \ker J_Z$. Step~1 does not use the invertibility of $J_Z$, so \eqref{eq:JA-JZ} holds, and for every $u \in U$,
  \begin{equation}
    0 \leq u^\top J_A u \leq u^\top J_Z u = 0 .
  \end{equation}
  Since $u^\top J_A u = \|R_A^{-1/2} H_A u\|^2$ and $u^\top J_Z u = \|R_Z^{-1/2} H_Z u\|^2$, this gives
  \begin{equation}
    H_A u = 0, \qquad H_Z u = 0 \qquad \text{for all } u \in U .
    \label{eq:H-vanish-on-U}
  \end{equation}
  Let $\Pi$ be the projector with kernel $U$ that is orthogonal with respect to the inner product $\langle u, v \rangle := u^\top \Sigma_M^{-1} v$, let $k := d_M - \dim U$, and let $B \in \mathbb{R}^{d_M \times k}$ have columns forming a basis of $\operatorname{range} \Pi$. Split
  \begin{equation}
    \begin{aligned}
      M - \mu_M & = M_1 + M_2,                                                      \\
      M_1       & := \Pi (M - \mu_M) = B m, \qquad m := (B^\top B)^{-1} B^\top M_1, \\
      M_2       & := (I - \Pi)(M - \mu_M) \in U .
    \end{aligned}
  \end{equation}
  The vectors $M_1$ and $M_2$ are jointly Gaussian with $\operatorname{Cov}(M_1, M_2) = \Pi \Sigma_M (I - \Pi)^\top = 0$, hence independent, and $m \in \mathbb{R}^k$ is Gaussian with positive-definite covariance, since $\operatorname{Cov}(M_1) = \Pi \Sigma_M \Pi^\top$ has rank $k$. By \eqref{eq:H-vanish-on-U}, $H_A M_2 = H_Z M_2 = 0$, so
  \begin{equation}
    A = \mu_A + (H_A B)\, m + N_A,
    \qquad
    Z = \mu_Z + (H_Z B)\, m + N_Z .
    \label{eq:reduced-channels}
  \end{equation}
  Thus $(m, A, Z)$ is an instance of the setting of the lemma with target $m$, channel matrices $H_A B$ and $H_Z B$, and information matrices $B^\top J_A B$ and $B^\top J_Z B$. Steps~2--4 of Case~1 use the hypothesis only through \eqref{eq:JA-JZ} and $J_Z \succ 0$, and both hold for the reduced instance: $B^\top J_A B \preceq B^\top J_Z B$ by congruence, and $B^\top J_Z B \succ 0$ because $Bc \in \operatorname{range}\Pi \setminus \{0\}$ is not in $U = \ker J_Z$ for $c \neq 0$. Case~1 applied to the reduced instance therefore yields, with
  \begin{equation}
    G := (H_A B)(B^\top J_Z B)^{-1} (H_Z B)^\top R_Z^{-1},
    \qquad
    S := R_A - (H_A B)(B^\top J_Z B)^{-1} (H_A B)^\top \succeq 0,
    \label{eq:reduced-G-S}
  \end{equation}
  a variable $A' := \mu_A + G(Z - \mu_Z) + W$, $W \sim \mathcal{N}(0, S)$ independent of $(M, Z)$, such that $(m, A') \overset{d}{=} (m, A)$ and $m - Z - A'$. The Markov chain $M - Z - A'$ holds because $A'$ is a function of $Z$ and $W$. Finally, $M = \mu_M + Bm + M_2$, where $M_2$ is independent of $(m, A)$ by \eqref{eq:reduced-channels} and of $(m, A')$ because $A'$ depends on $(m, N_Z, W)$ only; together with $(m, A') \overset{d}{=} (m, A)$ this gives $(M, A') \overset{d}{=} (M, A)$.
